import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_SIZE = 505;
    static int n, m, mod;
    static int[] factorials = new int[MAX_SIZE * 4];
    static int[] inverseFactorials = new int[MAX_SIZE * 4];
    static List<Integer> polyF = new ArrayList<>();
    static List<Integer> gPoly = new ArrayList<>();

    static int modAdd(int a, int b) {
        if (a + b >= mod) return a + b - mod;
        return a + b;
    }

    static void addMod(int[] a, int b) {
