            base = (int)((long)base * base % mod);
            exp >>= 1;
        }
        return res;
    }

    static void precompute(int n) {
        factorials[0] = 1;
        for (int i = 1; i <= n; i++) {
            factorials[i] = (int)((long)factorials[i - 1] * i % mod);
        }
        inverseFactorials[n] = modPow(factorials[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inverseFactorials[i] = (int)((long)inverseFactorials[i + 1] * (i + 1) % mod);
        }
    }

    static int choose(int n, int m) {
        if (n < 0 || m < 0 || n < m) return 0;
        return (int)((long)factorials[n] * inverseFactorials[n - m] % mod * inverseFactorials[m] % mod);
    }

    static int sumOfSeries(int x) {
        return x * (x + 1) / 2;
    }

    static List<Integer> multiplyPolynomials(List<Integer> A, List<Integer> B) {
        int sizeA = A.size();
        int sizeB = B.size();
        List<Integer> C = new ArrayList<>(Collections.nCopies(sizeA + sizeB - 1, 0));
        for (int i = 0; i < sizeA; i++) {
            for (int j = 0; j < sizeB; j++) {
                int val = (int)((long)A.get(i) * B.get(j) % mod);
                C.set(i + j, modAdd(C.get(i + j), val));
            }
        }
        return C;
    }

    static int G(int n, int m) {
        return choose(m + n - 1, n - 1);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        m = Integer.parseInt(st.nextToken());
        n = Integer.parseInt(st.nextToken());
        mod = Integer.parseInt(st.nextToken());

        precompute(m << 1);

        polyF.clear();
        gPoly.clear();

        for (int i = 0; i <= n; i++) {
            polyF.add(0);
            gPoly.add(0);
        }

        polyF.set(0, 1);
        for (int i = 1; i <= n; i++) {
            int val = 0;
            for (int j = 0; j <= i - 1; j++) {
                int term = (int)((long)polyF.get(j) * polyF.get(i - 1 - j) % mod);
                term = (int)((long)term * choose(i - 1, j) % mod);
                addMod(new int[]{val}, term);
            }
            val = (int)((long)val * (i + 1) % mod);
            polyF.set(i, val);
        }

        for (int i = 1; i <= n; i++) {
            int sumJ = sumOfSeries(i - 1);
            int sumJMinus = sumOfSeries(i - 1);
            int tempSum = 0;
            for (int j = 0; j <= i - 1; j++) {
                int term1 = (2L * polyF.get(j) * gPoly.get(i - 1 - j) % mod) * choose(i - 1, j) % mod;
                term1 = (int)(term1 * (i + 1) % mod);
                int term2 = (int)((long)choose(i - 1, j) * (sumJ + sumJMinus) % mod);
                term2 = (int)((long)term2 * polyF.get(j) % mod * polyF.get(i - 1 - j) % mod);
                int totalTerm = modAdd(term1, term2);
                addMod(new int[]{tempSum}, totalTerm);
            }
            gPoly.set(i, tempSum);
        }

        polyF.set(0, 0);
        for (int i = 0; i <= n; i++) {
            polyF.set(i, (int)((long)polyF.get(i) * inverseFactorials[i] % mod));
            gPoly.set(i, (int)((long)gPoly.get(i) * inverseFactorials[i] % mod));
        }

        int total = 0;
        for (int i = 1; i <= m - n + 1; i++) {
            int term = (int)((long)gPoly.get(n) * G(i + 1, m - i) % mod);
            term = (int)((long)term * factorials[n] % mod);
            term = (int)((long)term * i % mod);
            addMod(new int[]{total}, term);
            gPoly = multiplyPolynomials(gPoly, polyF);
            gPoly = gPoly.subList(0, n + 1);
        }

        System.out.println(total);
    }
}

